<?php $this->load->view('learn/english_course/player/_head');$cards=array_values($lesson['cards']); ?>
<style>
.answer-zone{min-height:46px;padding:7px;margin-top:8px;border:2px dashed #a78bfa;border-radius:12px;background:#faf5ff}.feedback{margin-top:8px;font-weight:800}.mission-answer{width:100%;min-height:82px;margin-top:9px;padding:10px;border:1px solid #93c5fd;border-radius:10px}.word-chip{cursor:pointer}.lesson-actions{grid-template-columns:repeat(4,1fr)!important}@media(max-width:640px){.lesson-actions{grid-template-columns:1fr!important}}
.activity-box{padding:13px 15px;margin:10px 0;background:#eff6ff;border:1px solid #bfdbfe;border-radius:14px}.activity-options{display:grid;gap:7px;margin-top:9px}.activity-option{padding:9px 12px;border:1px solid #bfdbfe;background:#fff;border-radius:10px;text-align:left;color:#1e3a8a;cursor:pointer}.activity-option.correct{background:#dcfce7;border-color:#86efac;color:#166534}.activity-option.wrong{background:#fee2e2;border-color:#fca5a5;color:#991b1b}.word-chip{display:inline-block;padding:7px 10px;margin:3px;background:#fff;border:1px solid #c4b5fd;border-radius:10px}.lesson-shell{max-width:920px;margin:auto}.lesson-head{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:14px}.step-dots{display:flex;gap:5px;max-width:48%;overflow:hidden}.step-dot{width:20px;height:7px;flex:0 0 auto;border:0;border-radius:99px;background:#dbeafe;transition:.35s}.step-dot.done,.step-dot.active{background:linear-gradient(90deg,#2563eb,#8b5cf6)}.step-dot.active{width:38px}.stage{position:relative;aspect-ratio:16/9;border-radius:26px;overflow:hidden;background:#dbeafe;border:1px solid #93c5fd}.scene-image{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transform:scale(1.015);will-change:transform,filter}.bubble{position:absolute;z-index:3;top:8%;width:38%;max-height:72%;overflow:auto;background:rgba(255,255,255,.96);padding:16px 19px;border-radius:22px 22px 4px 22px;box-shadow:0 10px 30px rgba(30,64,175,.2);font-size:clamp(16px,2.4vw,25px);font-weight:900;line-height:1.3;animation:pop .45s both}.bubble.right{right:5%}.bubble.left{left:5%;border-radius:22px 22px 22px 4px}.context-emoji{position:absolute;z-index:4;bottom:6%;font-size:48px;filter:drop-shadow(0 6px 4px rgba(0,0,0,.14))}.bubble.right~.context-emoji{right:5%}.bubble.left~.context-emoji{left:5%}.sentence-card{margin-top:14px;padding:22px}.translation{padding:12px 14px;background:#fffbeb;border-radius:12px;color:#92400e}.lesson-actions{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.next-row{display:flex;justify-content:space-between;gap:10px;margin-top:18px}.slide-in{animation:enter .4s both}.motion-float{animation:sceneFloat 3s ease-in-out infinite}.motion-bounce{animation:sceneBounce 2.4s ease-in-out infinite}.motion-wave{animation:sceneWave 3.5s ease-in-out infinite}.motion-zoom{animation:sceneZoom 6s ease-in-out infinite}.motion-slide{animation:sceneSlide 5s ease-in-out infinite}.motion-nod{animation:sceneNod 2.8s ease-in-out infinite}.motion-sway{animation:sceneSway 3.2s ease-in-out infinite}.motion-pop{animation:scenePop 2.6s ease-in-out infinite}.motion-glow{animation:sceneGlow 3s ease-in-out infinite}.motion-drift{animation:sceneDrift 7s ease-in-out infinite}@keyframes pop{from{opacity:0;transform:scale(.8) translateY(15px)}}@keyframes enter{from{opacity:0;transform:translateX(35px)}}@keyframes sceneFloat{50%{transform:scale(1.03) translateY(-5px)}}@keyframes sceneBounce{50%{transform:scale(1.025) translateY(4px)}}@keyframes sceneWave{50%{transform:scale(1.035) rotate(.35deg)}}@keyframes sceneZoom{50%{transform:scale(1.075)}}@keyframes sceneSlide{50%{transform:scale(1.045) translateX(-7px)}}@keyframes sceneNod{50%{transform:scale(1.03) rotate(-.3deg)}}@keyframes sceneSway{50%{transform:scale(1.04) translateX(5px)}}@keyframes scenePop{50%{transform:scale(1.06)}}@keyframes sceneGlow{50%{filter:saturate(1.12) brightness(1.05);transform:scale(1.035)}}@keyframes sceneDrift{50%{transform:scale(1.06) translate(5px,-3px)}}@media(max-width:640px){.lesson-head{align-items:flex-start}.step-dots{max-width:42%}.stage{aspect-ratio:4/5}.scene-image{object-position:center;height:62%}.bubble,.bubble.left,.bubble.right{left:5%;right:5%;top:auto;bottom:5%;width:90%;max-height:34%;font-size:17px;border-radius:18px}.context-emoji{top:4%;bottom:auto;right:5%!important;left:auto!important;font-size:40px}.lesson-actions{grid-template-columns:1fr}.next-row{flex-direction:column-reverse}.next-row .btn{width:100%}}
</style>
<div class="lesson-shell"><div class="lesson-head"><div><div class="eyebrow"><?=htmlspecialchars($lesson['level_title'])?> · <?=htmlspecialchars($lesson['unit_title'])?></div><h2 style="margin:4px 0"><?=htmlspecialchars($lesson['title'])?></h2></div><div class="step-dots" aria-label="Progres lesson"><?php foreach($cards as $i=>$unused):?><i class="step-dot <?=$i===0?'active':''?>"></i><?php endforeach?></div></div>
<div id="cardArea"><section class="stage"><img class="scene-image" id="sceneImage" alt="Adegan percakapan sesuai materi"><div class="bubble right" id="bubble"></div><span class="context-emoji" id="sceneEmoji"></span></section><section class="panel sentence-card"><div class="eyebrow" id="speaker"></div><h1 id="sentence" style="margin:7px 0 8px"></h1><div class="activity-box"><strong id="activityPrompt"></strong><div id="activityContent"></div></div><div class="translation" id="translation" hidden></div><div class="lesson-actions"><button class="btn speak" type="button">🔊 Dengarkan</button><button class="btn light slow" type="button">🐢 Perlahan</button><button class="btn light pronounce" type="button">🎙️ Latih Ucapan</button><button class="btn light hint" type="button">💡 Arti & Hint</button></div><div id="speechFeedback" class="feedback"></div><div class="next-row"><button class="btn light" id="prev" type="button">← Sebelumnya</button><button class="btn" id="next" type="button">Langkah Berikutnya →</button></div></section></div>
<form id="completeForm" method="post" action="<?=site_url('belajar/bahasa-inggris/lesson/'.$lesson['id'].'/complete')?>" hidden><input type="hidden" name="score" value="100"></form></div></main>
<script>
const cards=<?=json_encode($cards,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,pref=<?=json_encode($settings['tts_voice']??'us_female')?>,baseRate=<?=json_encode((float)($settings['tts_rate']??.9))?>,activityUrl=<?=json_encode(site_url('belajar/bahasa-inggris/lesson/'.$lesson['id'].'/activity'))?>,scenes={classroom:<?=json_encode(base_url('assets/english-course/scene-classroom-v1.png'))?>,home:<?=json_encode(base_url('assets/english-course/scene-home-v1.png'))?>,library:<?=json_encode(base_url('assets/english-course/scene-library-v1.png'))?>};let at=0;const area=document.getElementById('cardArea'),bubble=document.getElementById('bubble'),sceneImage=document.getElementById('sceneImage'),sentence=document.getElementById('sentence'),speaker=document.getElementById('speaker'),activityPrompt=document.getElementById('activityPrompt'),activityContent=document.getElementById('activityContent'),translation=document.getElementById('translation'),emoji=document.getElementById('sceneEmoji'),next=document.getElementById('next'),prev=document.getElementById('prev'),speechFeedback=document.getElementById('speechFeedback');
function speak(rate){EnglishCourseTTS.speak(cards[at].english,{rate:rate,preference:pref})}
function clean(s){return String(s||'').toLowerCase().replace(/[^a-z0-9' ]/g,'').replace(/\s+/g,' ').trim()}
function saveAttempt(c,answer,score,correct){const spoken=speechFeedback.textContent.includes('kecocokan'),type=spoken?'pronunciation':(c.activity_type||'practice'),body=new URLSearchParams({step_no:at+1+(spoken?1000:0),activity_type:type,answer_text:answer||'',score:String(score||0),is_correct:correct?'1':'0'});fetch(activityUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Requested-With':'XMLHttpRequest'},body:body.toString()}).catch(()=>{})}
function feedback(box,ok,message){let f=document.createElement('div');f.className='feedback';f.style.color=ok?'#15803d':'#b91c1c';f.textContent=(ok?'✓ ':'↻ ')+message;box.appendChild(f)}
function renderActivity(c){activityPrompt.textContent=c.prompt||'Pelajari contoh ini.';activityContent.innerHTML='';
 if(['listen_choice','image_choice'].includes(c.activity_type)){let choices=[...(c.choices||[])].sort(()=>Math.random()-.5),box=document.createElement('div');box.className='activity-options';choices.forEach(choice=>{let b=document.createElement('button');b.type='button';b.className='activity-option';b.textContent=choice;b.onclick=()=>{box.querySelectorAll('button').forEach(x=>x.disabled=true);let ok=choice===c.translation;b.classList.add(ok?'correct':'wrong');feedback(activityContent,ok,ok?'Tepat!':'Belum tepat. Jawabannya: '+c.translation);saveAttempt(c,choice,ok?100:0,ok)};box.appendChild(b)});activityContent.appendChild(box)}
 else if(c.activity_type==='sentence_builder'){let source=document.createElement('div'),answer=document.createElement('div'),chosen=[];source.style.marginTop='8px';answer.className='answer-zone';[...c.english.replace(/[.!?]/g,'').split(' ')].sort(()=>Math.random()-.5).forEach(word=>{let chip=document.createElement('button');chip.type='button';chip.className='word-chip';chip.textContent=word;chip.onclick=()=>{chosen.push(word);answer.textContent=chosen.join(' ');chip.disabled=true};source.appendChild(chip)});let check=document.createElement('button');check.type='button';check.className='btn light';check.style.marginTop='8px';check.textContent='Periksa Susunan';check.onclick=()=>{let value=chosen.join(' '),ok=clean(value)===clean(c.english);feedback(activityContent,ok,ok?'Susunannya benar.':'Coba lagi. Pola yang tepat: '+c.english);saveAttempt(c,value,ok?100:0,ok);check.disabled=true};activityContent.append(source,answer,check)}
 else if(c.activity_type==='error_check'){let box=document.createElement('div');box.className='activity-options';['Susunan sudah tepat','Perlu diperbaiki'].forEach((label,i)=>{let b=document.createElement('button');b.type='button';b.className='activity-option';b.textContent=label;b.onclick=()=>{box.querySelectorAll('button').forEach(x=>x.disabled=true);let ok=i===0;b.classList.add(ok?'correct':'wrong');feedback(activityContent,ok,ok?'Benar, contoh ini sudah tepat.':'Kalimat contoh ini sebenarnya sudah tepat.');saveAttempt(c,label,ok?100:0,ok)};box.appendChild(b)});activityContent.appendChild(box)}
 else if(c.activity_type==='dictation'){let input=document.createElement('input'),check=document.createElement('button');input.className='mission-answer';input.style.minHeight='auto';input.placeholder='Ketik kalimat yang terdengar…';check.type='button';check.className='btn light';check.style.marginTop='8px';check.textContent='Periksa Dikte';check.onclick=()=>{let value=input.value.trim(),ok=clean(value)===clean(c.english);feedback(activityContent,ok,ok?'Dikte tepat.':'Periksa lagi ejaan dan susunannya. Jawaban: '+c.english);saveAttempt(c,value,ok?100:0,ok);check.disabled=true};activityContent.append(input,check);setTimeout(()=>speak(baseRate),250)}
 else if(['guided_response','independent_mission'].includes(c.activity_type)){let note=document.createElement('div'),input=document.createElement('textarea'),save=document.createElement('button');note.className='muted';note.style.marginTop='6px';note.textContent=c.note||'';input.className='mission-answer';input.placeholder='Tulis jawabanmu dalam bahasa Inggris…';save.type='button';save.className='btn light';save.style.marginTop='8px';save.textContent='Simpan Jawaban';save.onclick=()=>{let value=input.value.trim();if(!value){input.focus();return}saveAttempt(c,value,100,true);feedback(activityContent,true,'Jawaban tersimpan. Coba ucapkan juga dengan lantang.');save.disabled=true;input.disabled=true};activityContent.append(note,input,save)}
 else {let note=document.createElement('div');note.className='muted';note.style.marginTop='6px';note.textContent=c.note||'Amati pola dan ucapkan contoh ini.';activityContent.appendChild(note)}}
function render(direction){const c=cards[at],props=['🎒','📚','✏️','🙋','⭐','💬','🎯','🌟','🗣️','👏'];area.classList.remove('slide-in');void area.offsetWidth;area.classList.add('slide-in');sceneImage.src=scenes[c.scene]||scenes.classroom;sceneImage.className='scene-image motion-'+(c.motion||['float','bounce','zoom'][at%3]);bubble.className='bubble '+(c.bubble_side==='left'?'left':'right');bubble.textContent='“'+c.english+'”';sentence.textContent=c.english;speaker.textContent='Langkah '+(at+1)+' dari '+cards.length+' · '+(c.speaker||'Practice');speechFeedback.textContent='';renderActivity(c);translation.innerHTML='<strong>'+c.translation+'</strong><br><small>'+((c.note)||'')+'</small>';translation.hidden=true;emoji.textContent=props[at%props.length];prev.disabled=at===0;next.textContent=at===cards.length-1?'Selesaikan Lesson ✓':'Langkah Berikutnya →';document.querySelectorAll('.step-dot').forEach((d,i)=>{d.className='step-dot '+(i<at?'done':i===at?'active':'')});}
document.querySelector('.speak').onclick=()=>speak(baseRate);document.querySelector('.slow').onclick=()=>speak(.68);document.querySelector('.pronounce').onclick=()=>{const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){speechFeedback.style.color='#92400e';speechFeedback.textContent='Latihan ucapan belum didukung browser ini. Gunakan Chrome/Edge dan izinkan mikrofon.';return}let r=new Recognition();r.lang='en-US';r.interimResults=false;speechFeedback.style.color='#1d4ed8';speechFeedback.textContent='🎙️ Mendengarkan… ucapkan kalimat di atas.';r.onresult=e=>{let heard=e.results[0][0].transcript,target=clean(cards[at].english),got=clean(heard),words=target.split(' '),hits=words.filter(w=>got.split(' ').includes(w)).length,score=Math.round(hits*100/Math.max(1,words.length)),ok=score>=70;speechFeedback.style.color=ok?'#15803d':'#b45309';speechFeedback.textContent=(ok?'✓ Bagus! ':'Coba sekali lagi. ')+'Terdengar: “'+heard+'” · kecocokan '+score+'%';saveAttempt(cards[at],heard,score,ok)};r.onerror=()=>{speechFeedback.style.color='#b45309';speechFeedback.textContent='Mikrofon belum dapat digunakan. Periksa izin mikrofon browser.'};r.start()};document.querySelector('.hint').onclick=function(){translation.hidden=!translation.hidden;this.textContent=translation.hidden?'💡 Buka Arti & Hint':'🙈 Sembunyikan Hint'};prev.onclick=()=>{if(at>0){at--;render(-1)}};next.onclick=()=>{if(at<cards.length-1){at++;render(1);setTimeout(()=>speak(baseRate),350)}else{next.disabled=true;next.textContent='Menyimpan progres…';document.getElementById('completeForm').submit()}};document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight')next.click();if(e.key==='ArrowLeft')prev.click()});render();
</script></body></html>
